    // Problem size
    int n = N;

    // Input and output arrays (1D)
    Buffer<num_t, 1> r(n);
    // We'll keep two buffers for y to implement double-buffering.
    Buffer<num_t, 1> y_prev(n);
    Buffer<num_t, 1> y_curr(n);

    // Initialize input
    init_array(n, r);

    // ----------------------------------------------------------------------
    // Halide setup for the Durbin kernel
    // ----------------------------------------------------------------------

    // ImageParams for the constant input r and the current y-vector
    ImageParam r_param(type_of<num_t>(), 1, "r_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    // Parameters for the current iteration index k and scalar alpha
    Param<int>   k_param("k");
    Param<num_t> alpha_param("alpha");

    // Set the constant input parameter once
    r_param.set(r);

    // ----------------------------------------------------------------------
    // Func to compute the inner sum:
    //
    //   sum_k = Σ_{i=0..k-1} r[k-i-1] * y[i]
    //
    // We rewrite it as:
    //
    //   sum_k = Σ_{t=0..k-1} r[t] * y[k-1-t]
    //
    // so that r is accessed in increasing index order (better locality).
    //
    // This is expressed as a reduction over t in [0, k_param).
    // ----------------------------------------------------------------------
    Func sum_func("sum");
    RDom t(0, k_param, "t");

    sum_func() = cast<num_t>(0);
    sum_func() += r_param(t) * y_param(k_param - 1 - t);

    // ----------------------------------------------------------------------
    // Func to compute the updated prefix of y:
    //
    //   for i in 0..k-1:
    //     y_new[i] = y_old[i] + alpha * y_old[k-i-1]
    //
    // We only realize this Func over i = 0..k-1, so all accesses are in-bounds.
    // ----------------------------------------------------------------------
    Var i("i");
    Func update_prefix("update_prefix");
    update_prefix(i) = y_param(i) + alpha_param * y_param(k_param - i - 1);

    // ----------------------------------------------------------------------
    // Scheduling for the Durbin pipelines
    //
    // The outer Durbin loop over k is inherently sequential due to
    // scalar recurrences in alpha, beta, and the y state. We keep k
    // on the host, and optimize the inner work (sum and prefix update)
    // with SIMD and threading.
    // ----------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);
    const int tile_i    = 128;  // tiles for the i-dimension in update_prefix

    // sum_func is a scalar reduction over t.
    // Vectorize across t to compute multiple products per iteration.
    sum_func
        .compute_root();

    sum_func.update()
        .vectorize(t, vec_width);

    // update_prefix is a 1D map over i. We:
    //   - tile i to create coarse-grain tasks,
    //   - parallelize across tiles,
    //   - vectorize within each tile.
    Var io("io"), ii("ii");
    update_prefix
        .compute_root()
        .split(i, io, ii, tile_i)
        .parallel(io)
        .vectorize(ii, vec_width);

    // JIT-compile the Halide code once, before timing
    sum_func.compile_jit(target);
    update_prefix.compile_jit(target);

    // ----------------------------------------------------------------------
    // Host-side Durbin recursion using the Halide Funcs for the inner work
    // ----------------------------------------------------------------------

    // Initial conditions:
    // y[0] = -r[0];
    // beta = 1.0;
    // alpha = -r[0];
    num_t alpha = -r(0);
    num_t beta  = (num_t)1.0;

    // Initialize y_prev
    y_prev(0) = -r(0);
    for (int idx = 1; idx < n; ++idx) {
        y_prev(idx) = (num_t)0;
    }

    // Attach the constant input r once (already done earlier, but harmless)
    r_param.set(r);

    // A small 1-element buffer to hold the scalar sum; re-used every
    // iteration to avoid repeated heap allocations.
    Buffer<num_t, 1> sum_buf(1);

    // Start timer
    auto start = std::chrono::high_resolution_clock::now();

    // Main Durbin loop:
    //
    // for (k = 1; k < n; k++) {
    //   beta = (1 - alpha*alpha) * beta;
    //   sum  = Σ_{i=0..k-1} r[k-i-1]*y[i];
    //   alpha = -(r[k] + sum) / beta;
    //   for (i=0; i<k; i++) y[i] = y[i] + alpha*y[k-i-1];
    //   y[k] = alpha;
    // }
    //
    // We implement sum and the y-prefix update with Halide Funcs,
    // and manage the per-iteration alpha/beta and buffer swapping on the host.
    for (int k = 1; k < n; ++k) {
        // Update beta using the previous alpha
        beta = ((num_t)1.0 - alpha * alpha) * beta;

        // Bind k and current y_prev into the Halide pipeline
        k_param.set(k);
        y_param.set(y_prev);

        // Compute sum_k = Σ_{t=0..k-1} r[t] * y_prev[k-1-t]
        sum_func.realize(sum_buf);
        num_t sum = sum_buf();

        // Compute the new alpha for this k
        alpha = -(r(k) + sum) / beta;

        // Bind the new alpha for the prefix-update Func
        alpha_param.set(alpha);

        // Compute y_curr[0..k-1] = y_prev[i] + alpha * y_prev[k-i-1]
        // We realize only the prefix [0, k), via a cropped view of y_curr.
        Buffer<num_t, 1> y_prefix = y_curr.cropped(0, 0, k);
        update_prefix.realize(y_prefix);

        // Set y_curr[k] = alpha
        y_curr(k) = alpha;

        // Swap y_prev and y_curr for the next iteration (double-buffering)
        std::swap(y_prev, y_curr);
    }

    // Stop timer
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

