    Param<int>   k_param("k");
    Param<num_t> alpha_param("alpha");

    // Attach the constant input r once. ImageParams are bound at runtime,
    // not baked into the JIT-compiled code, so this can also be done later.
    r_param.set(r);

    // ----------------------------------------------------------------------
    // Func to compute the inner sum:
    //
    //   sum = Σ_{i=0..k-1} r[k-i-1] * y[i]
    //
    // expressed as a reduction over i in [0, k_param)
    // ----------------------------------------------------------------------
    Func sum_func("sum");
    RDom ri(0, k_param, "ri");

    sum_func() = cast<num_t>(0);
    sum_func() += r_param(k_param - ri - 1) * y_param(ri);

    // ----------------------------------------------------------------------
    // Func to compute the updated prefix of y:
    //
    //   for i in 0..k-1:
    //     y_new[i] = y_old[i] + alpha * y_old[k-i-1]
    //
    // We only realize this Func over i = 0..k-1, so all accesses are in-bounds.
    // ----------------------------------------------------------------------
    Var i("i");
    Func update_prefix("update_prefix");
    update_prefix(i) = y_param(i) + alpha_param * y_param(k_param - i - 1);

    // ----------------------------------------------------------------------
    // Scheduling: improve locality and SIMD utilization for both Funcs
    // ----------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // sum_func is a scalar Func reduced over ri (0..k-1).
    // We vectorize across the reduction variable ri to get a SIMD dot-product
    // style loop for each k. Halide will handle non-multiple-of-vec_width
    // extents via tail handling.
    sum_func.compute_root();
    sum_func.update()
            .vectorize(ri, vec_width);

    // update_prefix is a pure 1D map over i, with symmetric access to y:
    //   y_new[i] = y_old[i] + alpha * y_old[k-1-i]
    // We tile and parallelize over i, and vectorize inside each tile.
    Var io("io"), ii("ii");
    const int tile_size = 256;  // tuned tile size; fits well in L1/L2 for typical N
    update_prefix
        .compute_root()
        .split(i, io, ii, tile_size)   // outer tiles 'io', inner 'ii'
        .parallel(io)                  // tiles can be computed in parallel (reads y_prev, writes y_curr)
        .vectorize(ii, vec_width);     // SIMD over contiguous ii within each tile

    // JIT-compile the Halide code once, before timing.
    // Using an explicit Target avoids recompilation if HL_TARGET is set.
    sum_func.compile_jit(target);
    update_prefix.compile_jit(target);

    // Small scalar buffer to hold the reduction result without re-allocating
    // each iteration. This is a 0-D buffer (single value).
    Buffer<num_t> sum_buf = Buffer<num_t>::scalar();

    // ----------------------------------------------------------------------
    // Host-side Durbin recursion using the Halide Funcs for the inner work
    // ----------------------------------------------------------------------

    // Initial conditions:
    // y[0] = -r[0];
    // beta = 1.0;
    // alpha = -r[0];
    num_t alpha = -r(0);
    num_t beta  = (num_t)1.0;

    // Initialize y_prev
    y_prev(0) = -r(0);
    for (int idx = 1; idx < n; ++idx) {
        y_prev(idx) = (num_t)0;
    }

    // ------------------------------------------------------------------
    // Main Durbin loop:
    //
    // for (k = 1; k < n; k++) {
    //   beta = (1 - alpha*alpha) * beta;
    //   sum  = Σ_{i=0..k-1} r[k-i-1]*y[i];
    //   alpha = -(r[k] + sum) / beta;
    //   for (i=0; i<k; i++) y[i] = y[i] + alpha*y[k-i-1];
    //   y[k] = alpha;
    // }
    //
    // The loop over k is inherently sequential (recurrence in alpha,
    // beta, and y). For each k, we call into Halide to 1) compute the
    // inner sum and 2) update the prefix of y using a double-buffered
    // representation (y_prev/y_curr).
    // ------------------------------------------------------------------

    // Start timer
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 1; k < n; ++k) {
        // Update beta using the previous alpha
        beta = ((num_t)1.0 - alpha * alpha) * beta;

        // Bind k and current y_prev into the Halide pipeline
        k_param.set(k);
        y_param.set(y_prev);

        // Compute sum = Σ_{i=0..k-1} r[k-i-1]*y_prev[i]
        sum_func.realize(sum_buf);
        num_t sum = sum_buf();

        // Compute the new alpha for this k
        alpha = -(r(k) + sum) / beta;

        // Bind the new alpha for the prefix-update Func
        alpha_param.set(alpha);

        // Compute y_curr[0..k-1] = y_prev[i] + alpha * y_prev[k-i-1]
        // We realize only the prefix [0, k), via a cropped view of y_curr.
        Buffer<num_t, 1> y_prefix = y_curr.cropped(0, 0, k);
        update_prefix.realize(y_prefix);

        // Set y_curr[k] = alpha (single scalar write outside Halide)
        y_curr(k) = alpha;

        // Swap y_prev and y_curr for the next iteration (O(1) pointer swap,
        // preserves the asymptotic O(n^2) complexity).
        std::swap(y_prev, y_curr);
    }

    // Stop timer
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ----------------------------------------------------------------------
    // Print result vector y (stored in y_prev) to stderr, one value per line,
    // mirroring the PolyBench print_array behavior.
    // ----------------------------------------------------------------------
    std::cerr << std::fixed << std::setprecision(2);
    for (int idx = 0; idx < n; ++idx) {
        std::cerr << y_prev(idx) << '\n';
    }

    // Print execution time (in seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
